def get_price(pid):
    v = redis.get(f"price:{pid}")
    if v is None:
        v = db.price(pid)
        redis.set(f"price:{pid}", v, ex=3600)
    return v

def update_price(pid, price):
    db.set_price(pid, price)      # committed
    redis.delete(f"price:{pid}")
